//! Byte-exact re-implementations of the legacy layouts, kept ONLY so the committed legacy vectors
//! (`fixtures/legacy_vectors.json`, generated by running the real legacy code) can be reproduced.
//!
//! Nothing here is used to sign or to authorise anything. In particular the legacy attestation
//! message `H_attestation_v0(outcome)` does not bind the event, the oracle or the announced R,
//! and the legacy announcement serialisation concatenates variable-length fields without
//! delimiters; both are superseded by the v1 messages in [`crate::attestation`].

use serde_json::{Map, Value};

use crate::attestation::Descriptor;
use crate::error::{Error, Result};
use crate::hash::tagged_hash;

/// `DLC_TAGS.ORACLE_ATTESTATION`.
pub const LEGACY_TAG_ATTESTATION: &str = "DLC/oracle/attestation/v0";
/// `DLC_TAGS.ORACLE_ANNOUNCEMENT`.
pub const LEGACY_TAG_ANNOUNCEMENT: &str = "DLC/oracle/announcement/v0";
/// `DLC_TAGS.ORACLE_NONCE`.
pub const LEGACY_TAG_NONCE: &str = "DLC/oracle/nonce/v0";

/// Legacy `hashAttestation(outcome)`.
pub fn hash_attestation(outcome: &str) -> [u8; 32] {
    tagged_hash(LEGACY_TAG_ATTESTATION, outcome.as_bytes())
}

/// Legacy `hashAnnouncement(data)`.
pub fn hash_announcement(data: &[u8]) -> [u8; 32] {
    tagged_hash(LEGACY_TAG_ANNOUNCEMENT, data)
}

/// Legacy `deriveNonceTweak(basePoint, eventId)`.
pub fn derive_nonce_tweak(base_point: &[u8], event_id: &str) -> [u8; 32] {
    let mut v = base_point.to_vec();
    v.extend_from_slice(event_id.as_bytes());
    tagged_hash(LEGACY_TAG_NONCE, &v)
}

/// `JSON.stringify(descriptor)` with the key order used by the legacy TypeScript objects.
pub fn descriptor_json(d: &Descriptor) -> String {
    fn s(x: &str) -> String {
        Value::String(x.to_string()).to_string()
    }
    match d {
        Descriptor::Enum { outcomes } => {
            let items: Vec<String> = outcomes.iter().map(|o| s(o)).collect();
            format!("{{\"type\":\"enum\",\"outcomes\":[{}]}}", items.join(","))
        }
        Descriptor::Binary { outcomes } => format!(
            "{{\"type\":\"binary\",\"outcomes\":[{},{}]}}",
            s(&outcomes[0]),
            s(&outcomes[1])
        ),
        Descriptor::Numeric(n) => format!(
            "{{\"type\":\"numeric\",\"base\":{},\"numDigits\":{},\"unit\":{},\"precision\":{},\"signed\":{}}}",
            n.base,
            n.num_digits,
            s(&n.unit),
            n.precision,
            n.signed
        ),
    }
}

/// Legacy `serializeAnnouncementData`: `eventId || JSON(descriptor) || int64_be(maturity) || R...`.
pub fn serialize_announcement(
    event_id: &str,
    descriptor_json: &str,
    maturity: i64,
    nonce_points: &[[u8; 32]],
) -> Vec<u8> {
    let mut v = Vec::new();
    v.extend_from_slice(event_id.as_bytes());
    v.extend_from_slice(descriptor_json.as_bytes());
    v.extend_from_slice(&maturity.to_be_bytes());
    for r in nonce_points {
        v.extend_from_slice(r);
    }
    v
}

/// Legacy `canonicalJSON`: recursively sort object keys (arrays keep order).
pub fn canonical_json(v: &Value) -> Value {
    match v {
        Value::Object(m) => {
            let mut keys: Vec<&String> = m.keys().collect();
            keys.sort();
            let mut out = Map::new();
            for k in keys {
                out.insert(k.clone(), canonical_json(&m[k]));
            }
            Value::Object(out)
        }
        Value::Array(a) => Value::Array(a.iter().map(canonical_json).collect()),
        other => other.clone(),
    }
}

/// Legacy `decodeSegwitOutput`: accepts trailing bytes after the program (a defect; see the
/// strict decoder in [`crate::handshake`]).
pub fn decode_segwit_lenient(script: &[u8]) -> Result<(u8, Vec<u8>)> {
    if script.len() < 2 {
        return Err(Error::Malformed("Script too short"));
    }
    let version = match script[0] {
        0x00 => 0,
        0x51..=0x60 => script[0] - 0x50,
        _ => return Err(Error::Malformed("Not a Segwit output")),
    };
    let len = usize::from(script[1]);
    let end = 2 + len;
    if script.len() < end {
        return Err(Error::Malformed("Program length mismatch"));
    }
    Ok((version, script[2..end].to_vec()))
}

/// Legacy `compactSize`: works below 0xfd and THROWS (TypeError) for larger sizes because
/// `Buffer.concat` receives a number from `writeUInt16LE`.
pub fn compact_size_legacy(n: usize) -> Result<Vec<u8>> {
    if n < 0xfd {
        Ok(vec![n as u8])
    } else {
        Err(Error::Rejected("legacy compactSize throws for n >= 0xfd"))
    }
}
